);
wwv_flow_imp_shared.create_translation(
 p_id=>wwv_flow_imp.id(6731766336625073)
,p_translated_flow_id=>102
,p_translate_to_id=>wwv_flow_imp.id(932918077484713392.102)
,p_translate_from_id=>wwv_flow_imp.id(932918077484713392)
,p_translate_column_id=>111
,p_translate_to_lang_code=>'en-us'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>'Select a PIT message to be displayed as a confirmation message before the page command is executed. If this parameter is set, a corresponding confirmation dialogue box will be added automatically.'
,p_translate_from_text=>unistr('W\00E4hlen Sie eine PIT-Meldung, die als Best\00E4tigungsnachricht vor dem Ausf\00FChren des Seitenkommandos gezeigt werden soll. Ist dieser Parameter gesetzt, wird automatisch ein entsprechender Best\00E4tigungsdialog hinzugef\00FCgt.')
